  ('starters', 'Starters', 'Small Plates, Big Beginnings', 'Fiery fries, crisp Manchurians and tandoor-kissed bites — the opening act to every Raaha meal.', '/images/dishes/chicken-65.webp', 0),
  ('grill-tandoor', 'Grill & Tandoor', 'From the Charcoal & Clay Oven', 'Marinated overnight, kissed by charcoal smoke and served sizzling — our grill is the heart of Raaha.', '/images/dishes/tandoori-chicken.webp', 1),
  ('biryani', 'Biryani', 'Seeraga Samba & Dum Specials', 'Fragrant short-grain rice layered with masala and sealed on dum, the way Madurai loves it.', '/images/dishes/chicken-dum-biryani.webp', 2),
  ('mains', 'Main Course', 'Curries & Comforting Gravies', 'Slow-simmered gravies from Chettinad to Old Delhi — made for scooping up with hot breads.', '/images/dishes/butter-chicken.webp', 3),
  ('south-indian', 'South Indian', 'Dosa, Idli & Tiffin Classics', 'Golden dosas, cloud-soft idlis and homestyle sambar — tiffin favourites served all day.', '/images/dishes/masala-dosa.webp', 4),
  ('breads-rice', 'Breads, Rice & Noodles', 'Naans, Rotis & Wok Tosses', 'Blistered tandoor breads, fragrant rice and Indo-Chinese wok favourites to complete the table.', '/images/dishes/garlic-naan.webp', 5),
  ('desserts', 'Desserts', 'A Sweet Finish', 'Warm jamuns, creamy kulfis and syrup-soaked classics — save a little room at the end.', '/images/dishes/gulab-jamun.webp', 6),
  ('beverages', 'Beverages', 'Chai, Coffee & Coolers', 'Kulhad chai, frothy filter coffee and chilled lassis to wash it all down.', '/images/dishes/mango-lassi.webp', 7)
